insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-153', 'enf', null, 'Na Escala de Coma de Glasgow com resposta pupilar (ECG-P), quando nenhuma das pupilas reage à luz:', '["subtraem-se 2 pontos do escore total de Glasgow.","somam-se 2 pontos ao escore.","o escore passa a ser 15.","subtrai-se 1 ponto.","a avaliação pupilar não altera o escore."]'::jsonb, 0, 'Uma pupila sem reação: −1; ambas sem reação: −2. O ECG-P pode variar de 1 a 15.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-154', 'enf', null, 'Pela fórmula de Parkland, um adulto de 70 kg com 20% de superfície corporal queimada (2º e 3º graus) deve receber nas primeiras 24 horas:', '["5.600 mL de Ringer lactato, sendo metade nas primeiras 8 horas.","2.800 mL em 24 horas, de forma igual.","1.400 mL nas primeiras 8 horas.","14.000 mL nas primeiras 8 horas.","560 mL em 24 horas."]'::jsonb, 0, '4 mL × 70 kg × 20% = 5.600 mL; 2.800 mL nas primeiras 8 h (contadas a partir da queimadura) e 2.800 mL nas 16 h seguintes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-155', 'enf', null, 'Na anafilaxia em adulto, a dose recomendada de adrenalina por via intramuscular é de:', '["0,5 mg (0,01 mg/kg, máximo de 0,5 mg), podendo repetir a cada 5 a 15 minutos.","1 mg EV em bolus como primeira escolha.","5 mg IM.","0,05 mg SC.","10 mg IM."]'::jsonb, 0, 'A via EV em bolus é reservada a situações de PCR ou choque refratário com monitorização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-156', 'enf', null, 'O instrumento utilizado para detectar delirium em pacientes de UTI, inclusive em ventilação mecânica, é o:', '["CAM-ICU.","RASS.","Braden.","APACHE II.","Glasgow."]'::jsonb, 0, 'O RASS avalia sedação/agitação e é pré-requisito para aplicar o CAM-ICU.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-157', 'enf', null, 'Para avaliação da dor em pacientes sedados e em ventilação mecânica, incapazes de se comunicar, utiliza-se a escala:', '["comportamental de dor (BPS - Behavioral Pain Scale).","numérica de 0 a 10.","de faces.","de Morse.","de Fugulin."]'::jsonb, 0, 'Avalia expressão facial, movimentos dos membros superiores e adaptação ao ventilador.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-158', 'enf', null, 'No choque séptico, a noradrenalina:', '["é o vasopressor de primeira escolha e deve ser infundida em bomba, preferencialmente por acesso venoso central.","deve ser administrada em bolus por via periférica.","é contraindicada.","deve ser diluída em água e dada por via oral.","é usada apenas para tratar bradicardia."]'::jsonb, 0, 'Meta usual: PAM ≥ 65 mmHg. Monitorar sinais de extravasamento e isquemia periférica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-159', 'enf', null, 'Segundo a Resolução CFM nº 2.173/2017 e a legislação de transplantes, diante da suspeita de morte encefálica, é obrigatório:', '["notificar a Central Estadual de Transplantes, sendo a morte encefálica de notificação compulsória.","aguardar autorização da família para iniciar o protocolo.","suspender todos os cuidados imediatamente.","realizar apenas um exame clínico.","dispensar exame complementar em adultos."]'::jsonb, 0, 'O protocolo inclui dois exames clínicos por médicos diferentes, teste de apneia e exame complementar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-160', 'enf', null, 'A esterilização por plasma de peróxido de hidrogênio é indicada para:', '["materiais termossensíveis, sendo incompatível com celulose (papel, algodão, tecidos).","todos os tecidos de algodão.","líquidos e pós.","materiais que suportam alta temperatura apenas.","embalagens de papel grau cirúrgico."]'::jsonb, 0, 'Processo de baixa temperatura, sem resíduos tóxicos; usa embalagens de Tyvek®.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-161', 'enf', null, 'Uma desvantagem da esterilização por óxido de etileno é:', '["a toxicidade do gás, que exige aeração dos materiais antes do uso.","a alta temperatura, que danifica plásticos.","o baixo custo, que reduz a qualidade.","a incapacidade de esterilizar materiais termossensíveis.","a necessidade de água destilada no processo."]'::jsonb, 0, 'O gás é tóxico, mutagênico e carcinogênico; exige controle ocupacional rigoroso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-162', 'enf', null, 'A limpeza de instrumentais em lavadora ultrassônica ocorre principalmente por:', '["cavitação, que remove sujidades de locais de difícil acesso.","esterilização a vapor.","radiação ionizante.","desinfecção química de alto nível.","fricção manual com escova."]'::jsonb, 0, 'Ondas sonoras formam microbolhas que implodem e desprendem a sujidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-163', 'enf', null, 'Segundo a RDC nº 15/2012, o monitoramento do processo de esterilização a vapor com indicador biológico deve ser feito:', '["no mínimo diariamente, em pacote desafio, e em todas as cargas com produtos implantáveis.","uma vez por mês.","uma vez por ano, na manutenção.","apenas quando houver suspeita de falha.","somente em autoclaves novas."]'::jsonb, 0, 'Cargas com implantáveis só devem ser liberadas após a leitura do indicador biológico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-164', 'enf', null, 'Para a prevenção da infecção do trato urinário associada a cateter vesical, a medida mais efetiva é:', '["evitar o uso desnecessário e remover o cateter o mais precocemente possível.","trocar o cateter a cada 24 horas.","irrigar a sonda rotineiramente.","manter a bolsa acima do nível da bexiga.","usar antibiótico profilático contínuo."]'::jsonb, 0, 'A duração da cateterização é o principal fator de risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-165', 'enf', null, 'Para a prevenção de infecção do sítio cirúrgico, a antibioticoprofilaxia, quando indicada, deve ser administrada:', '["até 60 minutos antes da incisão cirúrgica.","24 horas antes da cirurgia.","somente após o término da cirurgia.","por 10 dias após a alta.","no momento da sutura da pele."]'::jsonb, 0, 'O objetivo é obter nível tecidual adequado no momento da incisão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-166', 'enf', null, 'A sigla KPC refere-se a:', '["Klebsiella pneumoniae produtora de carbapenemase, bactéria multirresistente.","um tipo de vírus respiratório.","um antisséptico à base de clorexidina.","uma vacina contra pneumonia.","um teste de esterilização."]'::jsonb, 0, 'Exige precaução de contato e medidas rigorosas de controle de infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-167', 'enf', null, 'A densidade de incidência de infecção primária de corrente sanguínea associada a cateter central é calculada:', '["pelo número de infecções dividido pelo número de cateteres-dia, multiplicado por 1.000.","pelo número de infecções dividido pelo número de leitos, multiplicado por 100.","pelo número de óbitos dividido pelo número de infecções.","pelo número de cateteres dividido pelo número de pacientes.","pelo número de culturas positivas no ano."]'::jsonb, 0, 'O uso de cateteres-dia como denominador considera o tempo de exposição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-168', 'enf', null, 'Uma solução contém 4 mg de noradrenalina em 250 mL de soro glicosado. A concentração da solução é de:', '["16 mcg/mL.","4 mcg/mL.","62,5 mcg/mL.","1,6 mcg/mL.","160 mcg/mL."]'::jsonb, 0, '4 mg = 4.000 mcg; 4.000 ÷ 250 = 16 mcg/mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-169', 'enf', null, 'Dobutamina 250 mg diluída em 250 mL (1 mg/mL). Prescrição: 5 mcg/kg/min para paciente de 70 kg. A vazão na bomba de infusão será de:', '["21 mL/h.","5 mL/h.","35 mL/h.","350 mL/h.","2,1 mL/h."]'::jsonb, 0, '5 × 70 = 350 mcg/min × 60 = 21.000 mcg/h = 21 mg/h → 21 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-170', 'enf', null, 'Medicamentos com nomes ou embalagens semelhantes, que favorecem trocas e erros, são chamados de:', '["LASA (look-alike, sound-alike).","MAV (medicamentos de alta vigilância).","MIP (medicamentos isentos de prescrição).","genéricos.","fitoterápicos."]'::jsonb, 0, 'Estratégias: armazenamento separado, etiquetas de alerta e letras maiúsculas destacadas (tall man lettering).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-171', 'enf', null, 'O sistema de distribuição de medicamentos considerado mais seguro, por reduzir erros e desperdícios, é o:', '["sistema de dose unitária.","sistema coletivo.","sistema individualizado por 5 dias.","estoque livre nas unidades.","sistema de pedido verbal."]'::jsonb, 0, 'O medicamento chega pronto para administração, identificado por paciente e horário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-172', 'enf', null, 'Os frascos de insulina ainda não abertos devem ser armazenados:', '["sob refrigeração entre 2 °C e 8 °C, sem congelar.","no congelador.","em temperatura ambiente, expostos ao sol.","dentro do porta-luvas do carro.","em qualquer local, pois a insulina não altera."]'::jsonb, 0, 'Após aberta, pode ser mantida em temperatura ambiente (até cerca de 30 °C) pelo prazo indicado pelo fabricante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-173', 'enf', null, 'A morfina, segundo a Portaria SVS/MS nº 344/1998, é classificada na lista A1 (entorpecentes), e sua prescrição exige:', '["Notificação de Receita A (cor amarela).","receita comum, sem retenção.","Notificação de Receita B (cor azul).","receita de controle especial em duas vias, de cor branca, apenas.","nenhuma receita."]'::jsonb, 0, 'Lista B1 (psicotrópicos, como benzodiazepínicos): Notificação de Receita B (azul).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-174', 'enf', null, 'O curativo de hidrocoloide é indicado para feridas:', '["com pouco a moderado exsudato e sem infecção, podendo permanecer até 7 dias.","infectadas e muito exsudativas.","com exposição óssea.","com necrose seca extensa, em substituição ao desbridamento cirúrgico.","com sangramento ativo."]'::jsonb, 0, 'Forma gel em contato com o exsudato, mantendo o meio úmido; é contraindicado em feridas infectadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-175', 'enf', null, 'No uso da papaína em feridas, a concentração geralmente recomendada para tecido necrótico é de:', '["10%.","1%.","2%.","4%.","0,5%."]'::jsonb, 0, 'Usualmente: 2% em tecido de granulação; 4–6% em exsudato purulento/esfacelo; 10% em necrose.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-176', 'enf', null, 'O curativo de carvão ativado com prata é indicado principalmente para feridas:', '["infectadas, exsudativas e com odor.","limpas e secas.","em fase de epitelização.","com exposição de tendão sem exsudato.","de queimadura de 1º grau."]'::jsonb, 0, 'O carvão absorve o odor e a prata tem ação antimicrobiana.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-177', 'enf', null, 'A terapia por pressão negativa (TPN) em feridas tem como benefícios:', '["remoção de exsudato, redução do edema e estímulo à formação de tecido de granulação.","desbridamento enzimático de necrose seca.","tratamento de feridas com malignidade no leito.","substituição do controle de infecção.","indicação em sangramento ativo."]'::jsonb, 0, 'Contraindicações incluem malignidade no leito, necrose não desbridada e osteomielite não tratada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-178', 'enf', null, 'No tratamento da úlcera venosa de perna, a principal medida terapêutica é:', '["a terapia compressiva (como a bota de Unna), após excluir insuficiência arterial pelo índice tornozelo-braço.","manter a perna pendente o dia todo.","aplicar calor local intenso.","evitar a deambulação.","usar garrote abaixo do joelho."]'::jsonb, 0, 'A elevação dos membros também é recomendada; compressão em doença arterial pode causar isquemia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-179', 'enf', null, 'É característica da úlcera arterial:', '["dor que piora com a elevação do membro, pulsos diminuídos ou ausentes e bordas regulares, com leito pálido.","edema e dermatite ocre ao redor.","localização típica no maléolo medial com muito exsudato.","dor que piora com o membro pendente.","pulsos amplos e pele quente."]'::jsonb, 0, 'A úlcera venosa é que se localiza tipicamente no maléolo medial, com edema e hiperpigmentação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-180', 'enf', null, 'A lesão por pressão tissular profunda é descrita como:', '["pele intacta ou não, com área localizada e persistente de coloração vermelho-escura, marrom ou púrpura que não embranquece, ou separação epidérmica com leito escuro ou bolha de sangue.","eritema que embranquece à digitopressão.","perda parcial da pele com exposição da derme.","perda total da pele com gordura visível.","lesão coberta por esfacelo que impede ver a profundidade."]'::jsonb, 0, 'Resulta de pressão e cisalhamento intensos na interface osso-músculo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-181', 'enf', null, 'No pós-operatório de confecção de estomia intestinal, um estoma de coloração escura (arroxeada ou preta) sugere:', '["necrose, devendo ser comunicada imediatamente.","evolução normal.","excesso de cuidados com a pele.","hidratação adequada.","estoma bem vascularizado."]'::jsonb, 0, 'O estoma saudável é vermelho vivo, úmido e brilhante.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-182', 'enf', null, 'A irrigação de colostomia, como método de controle intestinal, é indicada para pacientes com colostomia:', '["no cólon descendente ou sigmoide, com fezes formadas.","em ileostomia.","em urostomia.","no cólon ascendente com fezes líquidas.","em qualquer estoma, desde o 1º dia de pós-operatório."]'::jsonb, 0, 'Requer orientação do enfermeiro estomaterapeuta e avaliação médica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-183', 'enf', null, 'A Resolução COFEN nº 736/2024 dispõe sobre a implementação do Processo de Enfermagem. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-184', 'enf', null, 'Segundo a Resolução COFEN nº 358/2009 (revogada pela Resolução COFEN nº 736/2024), a Sistematização da Assistência de Enfermagem (SAE):', '["organiza o trabalho profissional quanto ao método, ao pessoal e aos instrumentos, tornando possível a operacionalização do Processo de Enfermagem.","é sinônimo exato de Processo de Enfermagem, sem qualquer distinção conceitual.","é o registro das anotações feitas pelos técnicos de enfermagem.","dispensa o uso de referencial teórico.","é aplicada apenas em instituições hospitalares."]'::jsonb, 0, 'A SAE é a organização do trabalho; o Processo de Enfermagem é o instrumento metodológico que orienta o cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-185', 'enf', null, 'Na etapa de avaliação de enfermagem (antigo histórico), o enfermeiro:', '["coleta, de modo deliberado e sistemático, dados sobre a pessoa, a família ou a coletividade, por meio de entrevista, exame físico e outros métodos.","define as intervenções a serem realizadas.","executa as ações prescritas.","verifica, ao final do processo, os resultados alcançados, exclusivamente.","prescreve os medicamentos."]'::jsonb, 0, 'Os dados obtidos fundamentam o raciocínio diagnóstico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-186', 'enf', null, 'Na NANDA-I, o diagnóstico de enfermagem que descreve a motivação e o desejo de aumentar o bem-estar e concretizar o potencial de saúde é o diagnóstico de:', '["promoção da saúde.","risco.","síndrome.","foco no problema.","colaboração."]'::jsonb, 0, 'Tipos de diagnóstico NANDA-I: com foco no problema, de risco, de promoção da saúde e síndrome.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-187', 'enf', null, 'A Classificação Internacional para a Prática de Enfermagem (CIPE®) caracteriza-se por:', '["ser uma terminologia padronizada, que permite a elaboração de diagnósticos, resultados e intervenções de enfermagem a partir de um modelo de sete eixos.","classificar apenas as doenças, como a CID.","ser exclusiva para registros de técnicos de enfermagem.","dispensar o raciocínio clínico do enfermeiro.","ser utilizada apenas em unidades de terapia intensiva."]'::jsonb, 0, 'A CIPE é mantida pelo Conselho Internacional de Enfermeiros (ICN).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-188', 'enf', null, 'Associe as teóricas às respectivas teorias.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-189', 'enf', null, 'A teoria das Necessidades Humanas Básicas, de Wanda Horta, classifica as necessidades em:', '["psicobiológicas, psicossociais e psicoespirituais.","físicas, mentais e financeiras.","individuais, familiares e comunitárias.","básicas, intermediárias e complexas.","agudas, crônicas e terminais."]'::jsonb, 0, 'Horta baseou-se em Maslow e na classificação de João Mohana.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-190', 'enf', null, 'Durante a assistência, o enfermeiro realiza a coleta de dados e a avaliação clínica para identificar necessidades. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-191', 'enf', null, 'Na hierarquia de necessidades de Maslow, as necessidades situadas na base da pirâmide, que devem ser atendidas prioritariamente, são as:', '["fisiológicas.","de autorrealização.","de estima.","sociais (amor e pertencimento).","de segurança, acima das fisiológicas."]'::jsonb, 0, 'Ordem: fisiológicas, segurança, sociais, estima e autorrealização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-192', 'enf', null, 'A teoria de Imogene King, que enfatiza a interação entre enfermeiro e cliente para o estabelecimento e o alcance de metas compartilhadas, é a Teoria:', '["do Alcance de Metas.","do Déficit de Autocuidado.","das Relações Interpessoais.","dos Sistemas.","da Adaptação."]'::jsonb, 0, 'King descreve sistemas pessoais, interpessoais e sociais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-193', 'enf', null, 'Segundo a Resolução COFEN nº 543/2017, no dimensionamento do quadro de profissionais de enfermagem, deve ser acrescido um Índice de Segurança Técnica (IST) não inferior a:', '["15%.","5%.","30%.","50%.","1%."]'::jsonb, 0, 'O IST cobre ausências por férias, folgas e afastamentos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-194', 'enf', null, 'Em uma unidade, o enfermeiro gestor compartilha as decisões com a equipe, estimula a participação e a discussão dos problemas. Esse estilo de liderança é denominado:', '["democrático (participativo).","autocrático.","laissez-faire (liberal).","burocrático.","coercitivo."]'::jsonb, 0, 'No estilo autocrático, as decisões são centralizadas; no laissez-faire, há pouca interferência do líder.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-195', 'enf', null, 'Associe as teorias administrativas aos seus principais autores ou enfoques.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-196', 'enf', null, 'Na análise SWOT (FOFA), utilizada no planejamento estratégico de um serviço de enfermagem, os fatores do ambiente externo à organização são:', '["oportunidades e ameaças.","forças e fraquezas.","forças e oportunidades.","fraquezas e ameaças, apenas internas.","metas e indicadores."]'::jsonb, 0, 'Forças e fraquezas são fatores internos; oportunidades e ameaças, externos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-197', 'enf', null, 'Segundo o modelo de Donabedian para avaliação da qualidade em saúde, a proporção de pacientes que desenvolveram lesão por pressão em uma unidade é um indicador de:', '["resultado.","estrutura.","processo.","insumo.","custo."]'::jsonb, 0, 'Estrutura: recursos (área física, pessoal, equipamentos); processo: atividades realizadas; resultado: efeito do cuidado sobre o paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-198', 'enf', null, 'No modelo de Donabedian, a adesão da equipe ao protocolo de higiene das mãos é um indicador de:', '["processo.","estrutura.","resultado.","impacto financeiro.","produtividade."]'::jsonb, 0, 'Indicadores de processo avaliam se as práticas recomendadas estão sendo realizadas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-199', 'enf', null, 'No processo de acreditação hospitalar da Organização Nacional de Acreditação (ONA), o nível que corresponde à instituição que demonstra gestão integrada, com processos interagindo de forma sistêmica e mensuração de resultados, é o:', '["nível 2 (Acreditado Pleno).","nível 1 (Acreditado), focado apenas em segurança.","nível 3 (Acreditado com Excelência), exclusivamente estrutural.","nível 0, sem qualquer avaliação.","nível 4, inexistente na metodologia da ONA."]'::jsonb, 0, 'Nível 1: segurança; nível 2: gestão integrada; nível 3: excelência em gestão, com maturidade institucional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-200', 'enf', null, 'Na educação em saúde, a abordagem baseada nas ideias de Paulo Freire caracteriza-se por:', '["ser dialógica e problematizadora, valorizando o saber e a realidade dos participantes.","transmitir informações de forma vertical, do profissional para o usuário.","utilizar apenas palestras expositivas.","desconsiderar a experiência de vida das pessoas.","priorizar a punição de comportamentos de risco."]'::jsonb, 0, 'A educação bancária, que apenas deposita conteúdos, é criticada por Freire.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-201', 'enf', null, 'A Lei nº 7.498/1986 estabelece as atividades privativas do enfermeiro. Registre V para as atividades privativas do enfermeiro e F para as que não são privativas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-202', 'enf', null, 'O Decreto nº 94.406/1987 regulamenta a Lei nº 7.498/1986. É atividade privativa de todo enfermeiro:', '["a realização da consulta de enfermagem.","a aferição de sinais vitais e a verificação de peso e altura.","a realização de suturas simples de pele sem prescrição médica.","a realização de episiotomia, por qualquer enfermeiro.","a administração de medicamentos por via endovenosa."]'::jsonb, 0, 'A episiotomia é atribuição da enfermeira obstétrica; administração de medicamentos e sinais vitais podem ser feitos por técnicos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-203', 'enf', null, 'Segundo a Resolução COFEN nº 195/1997, o enfermeiro pode:', '["solicitar exames de rotina e complementares quando no exercício de suas atividades profissionais, em programas de saúde pública e rotinas aprovadas.","solicitar qualquer exame, inclusive invasivo, sem protocolo.","realizar diagnósticos médicos com base em exames.","prescrever cirurgias.","emitir atestado de óbito."]'::jsonb, 0, 'A solicitação de exames pelo enfermeiro está vinculada à consulta de enfermagem e a protocolos institucionais ou de saúde pública.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-204', 'enf', null, 'Segundo a Resolução COFEN nº 661/2021, no âmbito da equipe de enfermagem, a classificação de risco e a priorização da assistência em serviços de urgência são:', '["privativas do enfermeiro.","atribuições do técnico de enfermagem.","atribuições do auxiliar de enfermagem.","atribuições do recepcionista treinado.","facultativas, podendo ser feitas por qualquer profissional."]'::jsonb, 0, 'A classificação exige avaliação clínica e tomada de decisão, privativas do enfermeiro na equipe de enfermagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-205', 'enf', null, 'Segundo a Resolução COFEN nº 487/2015, é vedado aos profissionais de enfermagem o cumprimento de prescrição médica a distância (por telefone, mensagem ou e-mail), EXCETO:', '["em situações de urgência e emergência, desde que haja risco iminente de morte, e na regulação do atendimento pré-hospitalar.","em qualquer situação, desde que o médico confirme por mensagem.","nos plantões noturnos.","quando o paciente estiver estável.","quando o técnico autorizar."]'::jsonb, 0, 'Fora dessas exceções, a prescrição deve ser escrita, datada e assinada no prontuário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-206', 'enf', null, 'A Resolução COFEN nº 567/2018, que regulamenta a atuação da equipe de enfermagem no cuidado aos pacientes com feridas, estabelece que cabe ao enfermeiro:', '["avaliar, prescrever e executar curativos em todos os tipos de feridas, incluindo a prescrição de coberturas, e realizar desbridamento conforme sua capacitação.","apenas executar os curativos prescritos pelo médico.","delegar ao técnico a escolha das coberturas.","realizar desbridamento cirúrgico em centro cirúrgico.","abster-se de prescrever coberturas."]'::jsonb, 0, 'O técnico executa curativos sob supervisão, conforme prescrição do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-207', 'enf', null, 'O Código de Ética dos Profissionais de Enfermagem (Resolução COFEN nº 564/2017) estabelece proibições. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-208', 'enf', null, 'Segundo o Código de Ética (COFEN 564/2017), as infrações éticas são classificadas, quanto à gravidade, em:', '["leves, graves e gravíssimas.","simples e complexas.","culposas e dolosas, exclusivamente.","administrativas e penais.","primárias e secundárias."]'::jsonb, 0, 'A gravidade considera a natureza do ato, as circunstâncias e as consequências para a pessoa assistida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-209', 'enf', null, 'No Código de Ética dos Profissionais de Enfermagem, a penalidade de censura consiste em:', '["repreensão divulgada nas publicações oficiais do Conselho Federal e dos Conselhos Regionais e em jornais de grande circulação.","advertência reservada, sem publicação.","multa equivalente a dez anuidades.","proibição do exercício por 90 dias.","perda definitiva do registro."]'::jsonb, 0, 'A censura é mais grave que a advertência verbal e a multa, e menos grave que a suspensão e a cassação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-210', 'enf', null, 'O enfermeiro responsável técnico (RT) pelo serviço de enfermagem de uma instituição tem, entre suas atribuições:', '["organizar o serviço, dimensionar o pessoal, assegurar a implementação do Processo de Enfermagem e responder pelo serviço perante o COREN.","realizar a gestão financeira de toda a instituição.","prescrever medicamentos sem protocolo.","fiscalizar médicos e farmacêuticos.","exercer a função sem anotação no COREN."]'::jsonb, 0, 'A anotação de responsabilidade técnica é concedida pelo COREN ao enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-211', 'enf', null, 'No planejamento da assistência de enfermagem, o enfermeiro utiliza o Sistema de Classificação de Pacientes (SCP) com a finalidade de:', '["identificar o grau de dependência dos pacientes em relação à equipe de enfermagem e subsidiar o dimensionamento.","definir o diagnóstico médico.","estabelecer o valor da diária hospitalar.","classificar o risco na porta de entrada da urgência.","avaliar o risco de queda, exclusivamente."]'::jsonb, 0, 'Instrumentos como o de Fugulin são usados para essa classificação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-212', 'enf', null, 'Na elaboração de uma escala mensal de trabalho de enfermagem, o enfermeiro deve considerar, entre outros aspectos:', '["o dimensionamento de pessoal, a legislação trabalhista, o grau de dependência dos pacientes e a distribuição equilibrada de folgas.","apenas as preferências pessoais dos funcionários mais antigos.","a dispensa do enfermeiro no período noturno.","a concentração de todos os técnicos no plantão diurno.","a eliminação de folgas para cobrir déficits permanentes."]'::jsonb, 0, 'A escala adequada garante a cobertura assistencial e a segurança do paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-213', 'enf', null, 'A auditoria de enfermagem tem como finalidade principal:', '["avaliar a qualidade da assistência de enfermagem e a conformidade dos registros, subsidiando melhorias e a gestão de recursos.","punir profissionais que cometem erros.","substituir o Processo de Enfermagem.","realizar diagnósticos médicos.","controlar a vida pessoal dos trabalhadores."]'::jsonb, 0, 'A auditoria pode ser retrospectiva (prontuários) ou operacional (concorrente).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-214', 'enf', null, 'A educação permanente em saúde, na gestão do serviço de enfermagem, diferencia-se da educação continuada porque:', '["parte dos problemas do cotidiano do trabalho e envolve a equipe na transformação das práticas.","consiste apenas em cursos formais, desvinculados da realidade do serviço.","é destinada exclusivamente aos enfermeiros.","dispensa a participação dos trabalhadores no planejamento.","é realizada apenas uma vez por ano."]'::jsonb, 0, 'A educação continuada é mais voltada à atualização técnica, em geral por meio de cursos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-215', 'enf', null, 'No contexto da gestão de conflitos na equipe de enfermagem, a estratégia que busca a satisfação das necessidades de ambas as partes, com solução construída em conjunto, é a:', '["colaboração (ganha-ganha).","competição.","evitação.","acomodação.","imposição hierárquica."]'::jsonb, 0, 'A negociação colaborativa favorece soluções duradouras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-216', 'enf', null, 'O registro de enfermagem que contém a análise reflexiva dos dados referentes às últimas 24 horas, com avaliação da resposta do paciente às intervenções e orientação do planejamento, é:', '["a evolução de enfermagem, privativa do enfermeiro.","a anotação de enfermagem, realizada por toda a equipe.","o relatório de passagem de plantão.","a checagem da prescrição médica.","o registro de sinais vitais."]'::jsonb, 0, 'A anotação registra dados pontuais e cuidados prestados; a evolução é analítica e privativa do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-217', 'enf', null, 'Na etapa de planejamento de enfermagem, o enfermeiro:', '["define os resultados esperados e as intervenções de enfermagem para responder aos diagnósticos identificados.","coleta dados por meio do exame físico.","realiza as intervenções prescritas.","verifica apenas os sinais vitais.","encerra o Processo de Enfermagem."]'::jsonb, 0, 'O planejamento inclui a priorização dos diagnósticos e a prescrição de enfermagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-218', 'enf', null, 'No diagnóstico de enfermagem "Integridade da pele prejudicada relacionada à pressão sobre proeminências ósseas, evidenciada por destruição de camadas da pele", o trecho "evidenciada por destruição de camadas da pele" corresponde a:', '["característica definidora.","fator relacionado.","fator de risco.","título do diagnóstico.","resultado esperado."]'::jsonb, 0, 'Título: integridade da pele prejudicada; fator relacionado: pressão; característica definidora: destruição de camadas da pele.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-219', 'enf', null, 'Na Classificação dos Resultados de Enfermagem (NOC), os resultados são avaliados por meio de:', '["escalas do tipo Likert, de 5 pontos, que permitem medir a evolução do estado do paciente.","valores laboratoriais exclusivamente.","notas de 0 a 100 atribuídas pelo médico.","presença ou ausência de doença.","custos da internação."]'::jsonb, 0, 'A NOC permite comparar o estado do paciente antes e depois das intervenções.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-220', 'enf', null, 'Ao implantar um protocolo assistencial em uma unidade, o enfermeiro adota o ciclo PDCA. A etapa em que se verificam os resultados obtidos e se comparam com as metas estabelecidas é:', '["Check (verificar).","Plan (planejar).","Do (executar).","Act (agir).","Control (controlar), etapa adicional do ciclo."]'::jsonb, 0, 'Na etapa Act, padronizam-se as ações que deram certo ou corrigem-se as falhas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-221', 'enf', null, 'A ferramenta de qualidade que apresenta as causas de um problema em ordem decrescente de frequência, permitindo identificar as poucas causas responsáveis pela maior parte dos efeitos (princípio 80/20), é o:', '["diagrama de Pareto.","diagrama de Ishikawa.","fluxograma.","ciclo PDCA.","5W2H."]'::jsonb, 0, 'O Ishikawa organiza causas por categorias; o 5W2H é um plano de ação (o quê, por quê, onde, quando, quem, como e quanto).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-222', 'enf', null, 'A ferramenta 5W2H, usada na elaboração de planos de ação, responde às perguntas:', '["o quê, por quê, onde, quando, quem, como e quanto custa.","quem, quando e quanto, exclusivamente.","qual o diagnóstico médico e o tratamento.","quais são as forças, fraquezas, oportunidades e ameaças.","qual a causa raiz, apenas."]'::jsonb, 0, 'Em inglês: What, Why, Where, When, Who, How e How much.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-223', 'enf', null, 'Na gestão de materiais de uma unidade de enfermagem, a classificação ABC tem como objetivo:', '["classificar os itens conforme seu valor de consumo, priorizando o controle dos itens de maior impacto financeiro.","classificar os pacientes pela gravidade.","organizar os medicamentos em ordem alfabética.","definir a escala de trabalho.","classificar resíduos por grupo."]'::jsonb, 0, 'Itens A representam poucos itens com grande valor; itens C, muitos itens com pouco valor.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-224', 'enf', null, 'No contexto da segurança do paciente, a análise de causa raiz de um evento adverso grave tem como finalidade:', '["identificar os fatores sistêmicos que contribuíram para o evento e propor ações para evitar sua recorrência.","identificar o culpado e aplicar punição.","arquivar o caso sem medidas.","substituir a notificação ao sistema de vigilância.","comunicar o evento apenas à família."]'::jsonb, 0, 'O foco está no sistema e nos processos, não na culpabilização individual.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-225', 'enf', null, 'O Código de Ética dos Profissionais de Enfermagem estabelece direitos, deveres e proibições. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-226', 'enf', null, 'O sigilo profissional, segundo o Código de Ética, pode ser quebrado:', '["em casos previstos em lei, por ordem judicial ou com consentimento escrito da pessoa envolvida ou de seu representante legal.","sempre que um familiar solicitar.","quando o paciente receber alta.","para fins de divulgação em redes sociais.","após o óbito, livremente."]'::jsonb, 0, 'O dever de sigilo permanece mesmo após o óbito do paciente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-227', 'enf', null, 'Em uma unidade de saúde, o enfermeiro observa que um técnico de enfermagem não registrou a recusa de um paciente em receber um medicamento. A conduta adequada do enfermeiro é:', '["orientar o técnico sobre a obrigatoriedade do registro da recusa e de seus motivos, comunicando o fato ao prescritor.","ignorar, pois a recusa não precisa ser registrada.","administrar o medicamento à força.","registrar que o medicamento foi administrado.","punir o técnico com suspensão imediata."]'::jsonb, 0, 'A recusa do paciente capaz deve ser respeitada, registrada e comunicada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-228', 'enf', null, 'Segundo a Lei nº 7.498/1986, cabe ao enfermeiro, como integrante da equipe de saúde, EXCETO:', '["realizar o diagnóstico médico das doenças.","participar do planejamento, da execução e da avaliação da programação de saúde.","prevenir e controlar sistematicamente a infecção hospitalar e as doenças transmissíveis em geral.","participar da elaboração de medidas de prevenção e controle de danos ao paciente durante a assistência.","prestar assistência à gestante, à parturiente e à puérpera."]'::jsonb, 0, 'O diagnóstico nosológico (médico) não é atribuição do enfermeiro; o enfermeiro realiza diagnósticos de enfermagem.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-229', 'enf', null, 'O enfermeiro de uma unidade de internação percebe que a equipe frequentemente esquece de reavaliar o risco de queda dos pacientes. Considerando a gestão da qualidade, a melhor estratégia inicial é:', '["analisar o processo com a equipe, revisar o protocolo, capacitar os profissionais e monitorar a adesão por meio de indicadores.","punir os profissionais que esquecerem a avaliação.","abolir a avaliação de risco de queda.","transferir a responsabilidade aos acompanhantes.","aguardar a ocorrência de uma queda para agir."]'::jsonb, 0, 'Melhorias sustentáveis envolvem a equipe, a revisão dos processos e o monitoramento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-230', 'enf', null, 'A teoria de Betty Neuman, aplicável à enfermagem, compreende a pessoa como:', '["um sistema aberto que interage com estressores do ambiente, com linhas de defesa e resistência.","um ser que deve ser cuidado apenas em ambiente hospitalar.","um conjunto de necessidades exclusivamente fisiológicas.","um agente de autocuidado, apenas.","uma unidade isolada do ambiente."]'::jsonb, 0, 'O Modelo de Sistemas de Neuman orienta intervenções em prevenção primária, secundária e terciária.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-231', 'enf', null, 'Na Teoria do Déficit de Autocuidado de Orem, quando o paciente é incapaz de realizar ações de autocuidado e a enfermagem as realiza por ele, utiliza-se o sistema:', '["totalmente compensatório.","parcialmente compensatório.","de apoio-educação.","de adaptação.","transcultural."]'::jsonb, 0, 'No parcialmente compensatório, paciente e enfermagem dividem as ações; no de apoio-educação, o paciente realiza o autocuidado com orientação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-232', 'enf', null, 'Durante a consulta de enfermagem na Atenção Básica, o enfermeiro identifica um diagnóstico de enfermagem e elabora um plano de cuidados. Para a continuidade do cuidado, o registro deve:', '["ser realizado no prontuário do usuário, contendo dados de avaliação, diagnósticos, intervenções, resultados esperados e evolução.","ser feito apenas em caderno pessoal do enfermeiro.","ser dispensado nas consultas de rotina.","conter somente o nome do usuário e o horário.","ser registrado pelo agente comunitário de saúde."]'::jsonb, 0, 'O registro do Processo de Enfermagem é obrigatório e deve ser formal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-233', 'enf', null, 'O indicador "taxa de densidade de incidência de quedas" em uma unidade de internação é calculado por:', '["número de quedas dividido pelo número de pacientes-dia, multiplicado por 1.000.","número de quedas dividido pelo número de leitos.","número de quedas dividido pelo número de funcionários.","número de altas dividido pelo número de quedas.","número de quedas no ano, sem denominador."]'::jsonb, 0, 'O uso de pacientes-dia considera o tempo de exposição ao risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-234', 'enf', null, 'A gestão de riscos em serviços de saúde, prevista na RDC ANVISA nº 36/2013, é definida como:', '["aplicação sistêmica e contínua de políticas, procedimentos, condutas e recursos na identificação, análise, avaliação, comunicação e controle de riscos e eventos adversos.","contratação de seguros de responsabilidade civil.","punição de profissionais envolvidos em eventos.","fiscalização exclusiva dos equipamentos.","auditoria de contas hospitalares."]'::jsonb, 0, 'O Núcleo de Segurança do Paciente coordena essas ações na instituição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-235', 'enf', null, 'No contexto da comunicação efetiva entre profissionais, a técnica de "repetir de volta" (read-back) é especialmente recomendada para:', '["prescrições verbais e comunicação de resultados críticos de exames.","registros de rotina no prontuário.","orientações escritas ao paciente.","a elaboração de escalas de trabalho.","reuniões administrativas."]'::jsonb, 0, 'Quem recebe a informação a repete para confirmação por quem a transmitiu.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-236', 'enf', null, 'Durante a supervisão de enfermagem, o enfermeiro identifica que um técnico apresenta dificuldade na técnica de punção venosa. A conduta mais adequada é:', '["realizar orientação e treinamento em serviço, acompanhando o desempenho do profissional.","advertir publicamente o técnico.","proibir o técnico de realizar qualquer procedimento.","ignorar o problema, pois não houve dano.","transferir o técnico para outra unidade sem orientação."]'::jsonb, 0, 'A supervisão tem caráter educativo e visa à qualidade da assistência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-237', 'enf', null, 'Considerando a Resolução COFEN nº 736/2024, analise as afirmativas sobre a etapa de evolução de enfermagem.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-238', 'enf', null, 'No exercício da liderança situacional, o líder ajusta seu estilo conforme:', '["a maturidade (competência e comprometimento) dos liderados em relação à tarefa.","a idade dos liderados, exclusivamente.","o turno de trabalho.","o tempo de serviço do líder.","a preferência pessoal do líder, sem considerar a equipe."]'::jsonb, 0, 'Modelo de Hersey e Blanchard: determinar, persuadir, compartilhar e delegar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-239', 'enf', null, 'O enfermeiro supervisor recebe a notificação de um incidente sem dano, em que o medicamento errado foi interceptado antes de chegar ao paciente. Esse incidente é classificado como:', '["near miss (quase erro).","evento adverso grave.","incidente com dano leve.","sentinela.","reação adversa a medicamento."]'::jsonb, 0, 'Near miss: incidente que não atingiu o paciente; deve ser notificado e analisado para melhoria dos processos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-240', 'enf', null, 'Durante o Suporte Avançado de Vida Cardiovascular (SAVC) em um adulto com PCR em assistolia, a equipe segue o algoritmo adequado. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-241', 'enf', null, 'Na PCR em fibrilação ventricular, após o primeiro choque, a conduta imediata é:', '["reiniciar imediatamente as compressões torácicas por 2 minutos, antes de nova checagem do ritmo.","checar o pulso por 30 segundos.","aplicar novo choque imediatamente, sem compressões.","administrar atropina.","aguardar o efeito do choque por 1 minuto."]'::jsonb, 0, 'A checagem do ritmo é feita a cada 2 minutos de RCP; a adrenalina é administrada após o segundo choque e a amiodarona após o terceiro, conforme o algoritmo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-242', 'enf', null, 'Diante de um traçado de assistolia no monitor, antes de confirmar o ritmo, a equipe deve aplicar o protocolo da linha reta, que inclui:', '["checar as conexões dos cabos, aumentar o ganho do monitor e verificar o ritmo em outra derivação.","aplicar choque imediatamente.","administrar amiodarona.","suspender a RCP para checar pulso por 1 minuto.","trocar o paciente de leito."]'::jsonb, 0, 'Uma FV fina pode simular assistolia; problemas técnicos também podem gerar linha reta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-243', 'enf', null, 'Na atividade elétrica sem pulso (AESP), além da RCP e da adrenalina, é fundamental investigar e tratar as causas reversíveis, conhecidas como 5 Hs e 5 Ts. São exemplos de "Ts":', '["tamponamento cardíaco, pneumotórax hipertensivo, toxinas e trombose (coronária ou pulmonar).","hipovolemia, hipóxia e hipotermia.","taquicardia sinusal e tosse.","temperatura elevada e taquipneia.","tremores e tontura."]'::jsonb, 0, 'Hs: hipovolemia, hipóxia, H+ (acidose), hipo/hipercalemia e hipotermia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-244', 'enf', null, 'Durante a RCP com capnografia quantitativa em forma de onda, um valor de CO2 exalado (EtCO2) persistentemente inferior a 10 mmHg sugere:', '["compressões de baixa qualidade, indicando necessidade de melhorar a RCP.","retorno da circulação espontânea.","intubação seletiva bem-sucedida.","hiperventilação adequada.","necessidade de suspender a RCP imediatamente."]'::jsonb, 0, 'Um aumento abrupto e sustentado do EtCO2 pode indicar retorno da circulação espontânea.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-245', 'enf', null, 'Paciente com taquicardia supraventricular regular de QRS estreito, estável hemodinamicamente, não responde às manobras vagais. O medicamento de escolha e a forma de administração são:', '["adenosina 6 mg EV em bolus rápido, seguida de flush de 20 mL de soro fisiológico, com elevação do membro.","adenosina 6 mg diluída em 250 mL, em infusão lenta.","amiodarona 300 mg em bolus.","atropina 1 mg EV.","adrenalina 1 mg EV."]'::jsonb, 0, 'A adenosina tem meia-vida muito curta; por isso deve ser feita em bolus rápido, em acesso calibroso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-246', 'enf', null, 'Na cardioversão elétrica sincronizada, a sincronização tem a finalidade de:', '["liberar o choque sobre a onda R, evitando a descarga no período vulnerável da repolarização (onda T).","aumentar a energia do choque.","dispensar a sedação do paciente.","permitir o choque sem pás.","aplicar o choque durante a assistolia."]'::jsonb, 0, 'O choque sobre a onda T pode desencadear fibrilação ventricular. O paciente consciente deve ser sedado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-247', 'enf', null, 'Em paciente com bradicardia sintomática que não responde à atropina, uma das condutas indicadas é:', '["o marca-passo transcutâneo ou a infusão de dopamina ou adrenalina, conforme prescrição.","a desfibrilação imediata.","a adenosina em bolus.","a amiodarona em bolus.","a manobra vagal."]'::jsonb, 0, 'O marca-passo transcutâneo pode ser doloroso; deve-se considerar analgesia e sedação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-248', 'enf', null, 'No atendimento ao paciente com síndrome coronariana aguda, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-249', 'enf', null, 'No AVC isquêmico candidato à trombólise endovenosa, antes do início do trombolítico, a pressão arterial deve estar:', '["abaixo de 185 x 110 mmHg.","acima de 200 x 120 mmHg.","abaixo de 90 x 60 mmHg.","exatamente em 120 x 80 mmHg.","não há necessidade de controle pressórico."]'::jsonb, 0, 'Após a trombólise, a PA deve ser mantida abaixo de 180 x 105 mmHg nas primeiras 24 horas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-250', 'enf', null, 'No atendimento ao paciente com suspeita de AVC agudo, o exame de imagem inicial essencial para diferenciar o AVC isquêmico do hemorrágico é:', '["a tomografia computadorizada de crânio sem contraste.","a radiografia de tórax.","o eletroencefalograma.","a ultrassonografia abdominal.","a punção lombar."]'::jsonb, 0, 'A TC exclui hemorragia, o que é condição para a trombólise.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-251', 'enf', null, 'A escala utilizada para quantificar o déficit neurológico no AVC agudo, com itens como nível de consciência, motricidade, linguagem e sensibilidade, é a:', '["NIHSS (National Institutes of Health Stroke Scale).","escala de Braden.","escala de Morse.","escala RASS.","escala de Apgar."]'::jsonb, 0, 'A NIHSS orienta a decisão terapêutica e o acompanhamento evolutivo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-252', 'enf', null, 'São sinais de hipoperfusão tecidual que devem ser monitorados no paciente com sepse:', '["oligúria, alteração do nível de consciência, enchimento capilar lentificado e lactato elevado.","poliúria e hipertensão.","bradicardia e pele quente e seca, exclusivamente.","aumento do apetite.","hipotermia isolada, sem outros sinais."]'::jsonb, 0, 'O reconhecimento precoce e o pacote da primeira hora reduzem a mortalidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-253', 'enf', null, 'Associe os tipos de choque às suas características.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-254', 'enf', null, 'No paciente politraumatizado com escala de coma de Glasgow igual ou inferior a 8, a conduta indicada em relação à via aérea é:', '["garantir via aérea definitiva (intubação orotraqueal), mantendo a proteção da coluna cervical.","manter o paciente em observação sem intervenção.","oferecer oxigênio por cateter nasal a 2 L/min.","posicioná-lo em decúbito ventral.","realizar hiperextensão cervical."]'::jsonb, 0, 'O rebaixamento importante da consciência compromete a proteção da via aérea.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-255', 'enf', null, 'No cuidado ao paciente com traumatismo cranioencefálico grave, são medidas para prevenir a lesão cerebral secundária:', '["evitar hipotensão e hipóxia, manter a cabeceira elevada a cerca de 30° (se não houver contraindicação) e a cabeça alinhada, sem compressão das jugulares.","manter a cabeceira a 0° e a cabeça lateralizada.","promover hiperventilação prolongada em todos os casos.","restringir oxigênio.","infundir soro glicosado hipotônico em grande volume."]'::jsonb, 0, 'Hipotensão e hipóxia aumentam a mortalidade no TCE.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-256', 'enf', null, 'Paciente com trauma raquimedular cervical apresenta hipotensão acompanhada de bradicardia e pele quente. Esse quadro sugere:', '["choque neurogênico.","choque hipovolêmico.","choque cardiogênico por infarto.","tamponamento cardíaco.","pneumotórax hipertensivo."]'::jsonb, 0, 'A perda do tônus simpático causa vasodilatação e bradicardia; no choque hipovolêmico, há taquicardia e pele fria.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-257', 'enf', null, 'A tríade de Beck, composta por hipotensão, turgência jugular e abafamento das bulhas cardíacas, sugere:', '["tamponamento cardíaco.","pneumotórax simples.","choque séptico.","edema agudo de pulmão.","insuficiência renal aguda."]'::jsonb, 0, 'É emergência que exige descompressão do pericárdio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-258', 'enf', null, 'No trauma torácico, considera-se hemotórax maciço a drenagem imediata de sangue, pelo dreno torácico, de volume igual ou superior a:', '["1.500 mL.","100 mL.","300 mL.","500 mL.","50 mL."]'::jsonb, 0, 'Também indica gravidade a drenagem contínua superior a 200 mL/h por 2 a 4 horas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-259', 'enf', null, 'Na reposição volêmica do grande queimado adulto, a meta de débito urinário utilizada para guiar a infusão é de aproximadamente:', '["0,5 mL/kg/h.","5 mL/kg/h.","0,1 mL/kg/h.","10 mL/kg/h.","a diurese não é utilizada como parâmetro."]'::jsonb, 0, 'Em crianças, a meta é de cerca de 1 mL/kg/h; a sondagem vesical permite o controle horário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-260', 'enf', null, 'No paciente vítima de incêndio em ambiente fechado, são sinais sugestivos de lesão inalatória, que indicam avaliação precoce da via aérea:', '["queimaduras na face, pelos nasais chamuscados, fuligem na orofaringe, rouquidão e estridor.","queimadura de primeiro grau em membro inferior.","dor em queimadura de pequena extensão no braço.","bolhas na palma da mão.","febre baixa após 3 dias."]'::jsonb, 0, 'O edema de via aérea pode progredir rapidamente, exigindo intubação precoce.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-261', 'enf', null, 'Na intoxicação aguda por paracetamol, o antídoto utilizado é:', '["N-acetilcisteína.","naloxona.","flumazenil.","atropina.","vitamina K."]'::jsonb, 0, 'A eficácia é maior quando iniciado precocemente, guiado pelo tempo de ingestão e pelos níveis séricos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-262', 'enf', null, 'O carvão ativado, na descontaminação gastrointestinal de intoxicações, é contraindicado em:', '["ingestão de cáusticos e de hidrocarbonetos, e em pacientes com via aérea desprotegida.","intoxicação por medicamentos adsorvíveis em pacientes conscientes.","ingestões recentes, de até 1 hora.","qualquer intoxicação por comprimidos.","pacientes adultos com via aérea protegida."]'::jsonb, 0, 'Cáusticos não são adsorvidos e o carvão dificulta a endoscopia; hidrocarbonetos aumentam o risco de aspiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-263', 'enf', null, 'Na intoxicação por monóxido de carbono, a oximetria de pulso convencional pode apresentar valores falsamente normais porque:', '["o oxímetro não diferencia a carboxi-hemoglobina da oxi-hemoglobina.","o monóxido de carbono aumenta a perfusão periférica.","o paciente sempre apresenta cianose.","o monóxido de carbono reduz a frequência cardíaca.","o oxímetro mede diretamente o monóxido no sangue."]'::jsonb, 0, 'O tratamento inclui oxigênio a 100% por máscara com reservatório ou oxigenoterapia hiperbárica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-264', 'enf', null, 'No tratamento da cetoacidose diabética, antes do início da insulina endovenosa, o enfermeiro deve atentar para o nível sérico de potássio porque:', '["a insulina desloca o potássio para dentro das células, podendo agravar uma hipocalemia; se o potássio estiver baixo, ele deve ser reposto antes.","a insulina eleva o potássio sérico.","o potássio não sofre alteração na cetoacidose.","a hidratação venosa eleva perigosamente o potássio.","o potássio deve ser suspenso em todos os casos."]'::jsonb, 0, 'Os protocolos recomendam repor o potássio quando estiver abaixo de 3,3 mEq/L antes de iniciar a insulina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-265', 'enf', null, 'No eletrocardiograma, a presença de onda U proeminente e achatamento da onda T sugere:', '["hipocalemia.","hipercalemia.","hipercalcemia.","hipermagnesemia.","hiponatremia."]'::jsonb, 0, 'Na hipercalemia, a alteração típica é a onda T apiculada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-266', 'enf', null, 'A emergência hipertensiva diferencia-se da urgência hipertensiva pela presença de:', '["lesão aguda e progressiva de órgão-alvo, como encefalopatia, edema agudo de pulmão, síndrome coronariana aguda ou dissecção de aorta.","pressão arterial acima de 140 x 90 mmHg, apenas.","cefaleia leve isolada.","ausência de sintomas.","uso irregular de anti-hipertensivo, apenas."]'::jsonb, 0, 'Na emergência, a redução da PA é feita com medicação endovenosa e monitorização em ambiente de terapia intensiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-267', 'enf', null, 'Paciente hipertenso apresenta dor torácica súbita, intensa, descrita como "rasgando", com irradiação para o dorso e diferença de pressão arterial entre os membros superiores. A principal hipótese diagnóstica é:', '["dissecção aguda de aorta.","pericardite viral.","crise de ansiedade.","pneumonia.","refluxo gastroesofágico."]'::jsonb, 0, 'Trata-se de emergência; trombolíticos são contraindicados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-268', 'enf', null, 'São sinais e sintomas sugestivos de tromboembolismo pulmonar:', '["dispneia súbita, taquicardia, dor torácica pleurítica e hipoxemia, especialmente em pacientes com fatores de risco para trombose.","febre alta e tosse produtiva há 10 dias.","dor abdominal em cólica e diarreia.","poliúria e polidipsia.","prurido generalizado."]'::jsonb, 0, 'Imobilização, cirurgias recentes, câncer e trombose venosa profunda são fatores de risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-269', 'enf', null, 'No paciente com crise asmática, são sinais de gravidade que indicam risco de insuficiência respiratória:', '["dificuldade para falar frases completas, uso de musculatura acessória, cianose, confusão e tórax silencioso à ausculta.","sibilos leves e fala normal.","tosse seca noturna isolada.","frequência respiratória normal com boa saturação.","pico de fluxo expiratório normal."]'::jsonb, 0, 'O "tórax silencioso" indica obstrução grave, com pouco fluxo de ar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-270', 'enf', null, 'Na síndrome compartimental aguda em membro após trauma, o sinal mais precoce e importante é:', '["dor desproporcional à lesão, que piora com o estiramento passivo dos músculos.","ausência de pulso distal.","palidez tardia.","paralisia completa imediata.","febre."]'::jsonb, 0, 'A ausência de pulso é sinal tardio; a fasciotomia é o tratamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-271', 'enf', null, 'Na PCR em gestante com útero palpável na altura da cicatriz umbilical ou acima, recomenda-se, durante a RCP:', '["o deslocamento manual do útero para a esquerda, para reduzir a compressão aortocava.","manter a gestante em decúbito ventral.","não realizar compressões torácicas.","aguardar o parto antes de iniciar a RCP.","realizar compressões abdominais."]'::jsonb, 0, 'Se não houver retorno da circulação, a equipe considera a cesárea de emergência (perimortem) em poucos minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-272', 'enf', null, 'Na escala de coma de Glasgow, o paciente que, ao estímulo doloroso, leva a mão até o local do estímulo recebe na resposta motora a pontuação:', '["5 (localiza a dor).","6 (obedece a comandos).","4 (retirada inespecífica).","3 (flexão anormal/decorticação).","2 (extensão anormal/descerebração)."]'::jsonb, 0, 'Resposta motora: 6 obedece; 5 localiza; 4 retira; 3 flexão anormal; 2 extensão; 1 nenhuma.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-273', 'enf', null, 'Na criança com bradicardia (FC < 60 bpm) acompanhada de sinais de má perfusão, apesar de oxigenação e ventilação adequadas, a conduta indicada pelo PALS é:', '["iniciar compressões torácicas (RCP).","aguardar e reavaliar em 10 minutos.","administrar adenosina.","realizar cardioversão sincronizada.","oferecer líquidos por via oral."]'::jsonb, 0, 'Em crianças, a bradicardia com hipoperfusão é sinal de colapso iminente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-274', 'enf', null, 'Na emergência pediátrica, quando o acesso venoso periférico não é obtido rapidamente em uma criança em PCR ou choque grave, a alternativa recomendada é o acesso:', '["intraósseo, geralmente na região proximal da tíbia.","intramuscular para todas as drogas.","subcutâneo.","intradérmico.","por sonda nasogástrica."]'::jsonb, 0, 'Pela via intraóssea podem ser infundidos fluidos, medicamentos e hemocomponentes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-275', 'enf', null, 'Na PCR pediátrica, a dose de adrenalina endovenosa ou intraóssea é de:', '["0,01 mg/kg (0,1 mL/kg da solução 0,1 mg/mL), repetida a cada 3 a 5 minutos.","1 mg para qualquer peso.","0,5 mg/kg.","0,1 mg/kg, uma única vez.","10 mg/kg."]'::jsonb, 0, 'A dose máxima por administração é de 1 mg.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-276', 'enf', null, 'Na desfibrilação pediátrica em fibrilação ventricular, a energia inicial recomendada é de:', '["2 J/kg, aumentando para 4 J/kg no choque seguinte.","200 J em qualquer idade.","0,5 J/kg.","10 J/kg.","360 J."]'::jsonb, 0, 'Os choques subsequentes podem ser de 4 J/kg ou mais, sem ultrapassar 10 J/kg ou a dose adulta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-277', 'enf', null, 'Na criança com pulso presente, mas com respiração inadequada (parada respiratória), a ventilação de resgate recomendada pelas diretrizes atuais é de:', '["1 ventilação a cada 2 a 3 segundos (20 a 30 por minuto).","1 ventilação a cada 10 segundos.","2 ventilações por minuto.","60 ventilações por minuto.","não se ventila criança com pulso."]'::jsonb, 0, 'O pulso deve ser reavaliado a cada 2 minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-278', 'enf', null, 'Sobre a reanimação neonatal em sala de parto, conforme as diretrizes da Sociedade Brasileira de Pediatria (2022), registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-279', 'enf', null, 'Um recém-nascido a termo nasce hipotônico e sem respiração. Após 30 segundos de VPP efetiva com ar ambiente, mantém FC de 50 bpm. O próximo passo, conforme as diretrizes de 2022, é:', '["iniciar massagem cardíaca coordenada com a VPP, agora com oxigênio suplementar.","administrar adrenalina endotraqueal imediatamente.","iniciar adrenalina endovenosa sem reavaliar a ventilação.","aumentar a pressão da VPP por mais 30 segundos antes de reavaliar.","realizar a intubação sem iniciar a massagem."]'::jsonb, 0, 'A adrenalina é indicada se a FC continuar abaixo de 60 bpm após 60 segundos de massagem coordenada com VPP.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-280', 'enf', null, 'Nos passos iniciais da reanimação neonatal, a avaliação imediata ao nascimento considera três perguntas: gestação a termo, respiração ou choro e tônus muscular. Se a resposta a qualquer uma for "não", o recém-nascido deve:', '["ser levado à mesa de reanimação para os passos iniciais (prover calor, posicionar a cabeça, aspirar se necessário e secar).","permanecer em contato pele a pele com a mãe, sem intervenção.","receber banho imediato.","receber adrenalina imediatamente.","ser alimentado no seio materno."]'::jsonb, 0, 'O RN vigoroso, a termo, com respiração e tônus adequados, permanece com a mãe.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-281', 'enf', null, 'Na reanimação neonatal, a frequência recomendada da ventilação com pressão positiva é de:', '["40 a 60 ventilações por minuto.","10 a 12 ventilações por minuto.","100 a 120 ventilações por minuto.","20 ventilações por minuto.","uma ventilação a cada 6 segundos."]'::jsonb, 0, 'Ritmo prático: "aperta, solta, solta".') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-282', 'enf', null, 'No acolhimento com classificação de risco de uma unidade de urgência, o enfermeiro recebe um paciente com dor torácica intensa e suspeita de infarto. A conduta correta é:', '["priorizar o atendimento imediato, pois a dor torácica intensa exige avaliação médica e ECG sem demora.","reavaliar a dor após duas horas, se o paciente estiver consciente.","encaminhar o paciente para aguardar por ordem de chegada.","liberar o paciente com analgésico.","solicitar exames e aguardar resultados antes de qualquer atendimento."]'::jsonb, 0, 'Atrasos no atendimento ao infarto aumentam a área de necrose e a mortalidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-283', 'enf', null, 'As emergências obstétricas, pediátricas e psiquiátricas demandam abordagens específicas. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-284', 'enf', null, 'No atendimento pré-hospitalar a uma vítima de politrauma, motociclista inconsciente com capacete, a ação prioritária na abordagem da via aérea com controle cervical, quando há comprometimento da via aérea, é:', '["remover o capacete com técnica de duas pessoas, mantendo a estabilização da coluna, para permitir o manejo da via aérea.","realizar hiperextensão do pescoço para abrir a via aérea.","ignorar a via aérea e focar apenas nas hemorragias visíveis.","remover o capacete sem estabilização da coluna cervical.","manter o capacete e oferecer oxigênio por cateter."]'::jsonb, 0, 'Com via aérea comprometida, a retirada do capacete é necessária, sempre com estabilização cervical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-285', 'enf', null, 'No trauma pediátrico, a escala utilizada para avaliar o nível de consciência e classificar a gravidade do TCE em crianças pré-verbais é a:', '["escala de coma de Glasgow pediátrica, que adapta as respostas verbal e motora à idade.","escala de Ramsay.","escala de Cincinnati.","escala de Braden Q.","escala de Apgar."]'::jsonb, 0, 'O Triângulo de Avaliação Pediátrica avalia a impressão geral, mas não classifica a gravidade do TCE.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-286', 'enf', null, 'No paciente vítima de trauma com sinais de choque hipovolêmico, a estratégia atual de reposição volêmica no atendimento inicial inclui:', '["controle precoce da hemorragia e reposição criteriosa de cristaloides, com uso precoce de hemocomponentes quando indicado.","infusão de grandes volumes de soro glicosado.","restrição total de líquidos até a cirurgia em qualquer caso.","uso de vasopressores como primeira medida.","reposição apenas por via oral."]'::jsonb, 0, 'O excesso de cristaloides pode agravar a coagulopatia, a acidose e a hipotermia (tríade letal).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-287', 'enf', null, 'A tríade letal do trauma, que deve ser prevenida no paciente com hemorragia grave, é composta por:', '["hipotermia, acidose e coagulopatia.","hipertensão, bradicardia e apneia.","febre, taquicardia e leucocitose.","hiperglicemia, poliúria e polidipsia.","dor, ansiedade e insônia."]'::jsonb, 0, 'Medidas: controle do sangramento, aquecimento e transfusão balanceada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-288', 'enf', null, 'No paciente com suspeita de tromboembolismo pulmonar maciço, com instabilidade hemodinâmica, uma das terapias consideradas é:', '["a trombólise sistêmica, conforme avaliação médica e ausência de contraindicações.","a administração de vitamina K.","a restrição de oxigênio.","o uso exclusivo de analgésicos.","a deambulação precoce imediata."]'::jsonb, 0, 'Pacientes estáveis geralmente recebem anticoagulação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-289', 'enf', null, 'Na regulação médica das urgências, a decisão de transferir um paciente grave entre hospitais:', '["é médica, cabendo ao serviço de origem esgotar seus recursos e manter a responsabilidade pelo paciente até que ele seja recebido pela equipe de transporte ou pelo serviço receptor.","cabe exclusivamente ao enfermeiro.","depende apenas da disponibilidade de leito informada pelo hospital de destino.","pode ser feita sem comunicação à central de regulação.","é decidida pelo motorista da ambulância."]'::jsonb, 0, 'Portaria nº 2.048/2002.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-290', 'enf', null, 'No transporte inter-hospitalar de um paciente crítico em ventilação mecânica, cabe ao enfermeiro, entre outras ações:', '["verificar a estabilidade do paciente, a fixação dos dispositivos, as drogas em bomba, a reserva de oxigênio e os equipamentos de monitorização.","suspender todas as infusões durante o transporte.","desconectar o paciente do ventilador e ventilar com bolsa sem oxigênio.","dispensar a monitorização durante o percurso.","transportar o paciente sem prontuário."]'::jsonb, 0, 'O planejamento do transporte reduz eventos adversos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-291', 'enf', null, 'No paciente com dor torácica e ECG com supradesnivelamento do segmento ST, as estratégias de reperfusão incluem:', '["angioplastia primária ou trombólise química, conforme disponibilidade e tempo de evolução.","repouso e observação por 24 horas.","analgesia isolada.","apenas oxigênio e repouso.","alta com orientação de retorno."]'::jsonb, 0, 'Metas: porta-agulha ≤ 30 minutos; porta-balão ≤ 90 minutos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-292', 'enf', null, 'No manejo do paciente com intoxicação por benzodiazepínico com rebaixamento de consciência, o uso do flumazenil deve ser feito com cautela porque:', '["pode precipitar convulsões, especialmente em usuários crônicos de benzodiazepínicos ou em intoxicações mistas.","aumenta a sedação.","causa hipoglicemia grave.","é ineficaz em qualquer situação.","provoca hipertensão maligna em todos os casos."]'::jsonb, 0, 'O suporte ventilatório e hemodinâmico é a base do tratamento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-293', 'enf', null, 'Paciente adulto chega à emergência após ingestão de grande quantidade de comprimidos há 40 minutos, consciente e com via aérea protegida. A descontaminação com carvão ativado:', '["pode ser considerada, conforme o tipo de substância e a avaliação médica, por ter sido realizada em até 1 hora da ingestão.","é contraindicada em qualquer intoxicação medicamentosa.","deve ser feita somente após 24 horas.","substitui a monitorização do paciente.","deve ser associada obrigatoriamente à indução de vômito."]'::jsonb, 0, 'A indução de vômito não é recomendada; o CIATox pode orientar a conduta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-294', 'enf', null, 'Na avaliação inicial do paciente vítima de queimadura elétrica de alta voltagem, a equipe deve priorizar:', '["a monitorização cardíaca, pelo risco de arritmias, e a avaliação de lesões internas e de mioglobinúria.","a aplicação de pomadas nas lesões de entrada e saída.","a alta precoce, se a lesão de pele for pequena.","a restrição hídrica.","a imobilização gessada imediata."]'::jsonb, 0, 'As lesões visíveis subestimam o dano profundo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-295', 'enf', null, 'No paciente vítima de afogamento, mesmo assintomático após o resgate, recomenda-se:', '["observação clínica por algumas horas, pelo risco de piora respiratória tardia.","liberação imediata sem avaliação.","administração de diurético para retirar a água dos pulmões.","manobra de Heimlich para retirar a água.","dieta oral imediata."]'::jsonb, 0, 'Alguns pacientes desenvolvem edema pulmonar e insuficiência respiratória horas após o evento.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-296', 'enf', null, 'Durante o atendimento a uma PCR intra-hospitalar, o papel do enfermeiro líder da equipe de enfermagem inclui:', '["organizar as funções da equipe, garantir compressões de qualidade e revezamento, preparar e administrar medicamentos conforme orientação e registrar os eventos.","realizar todas as funções sozinho.","deixar a sala para buscar materiais durante toda a RCP.","decidir isoladamente pela interrupção da reanimação.","dispensar o registro dos horários das intervenções."]'::jsonb, 0, 'A comunicação em alça fechada e a definição clara de papéis aumentam a eficiência da equipe.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-297', 'enf', null, 'Nos cuidados pós-parada cardiorrespiratória, após o retorno da circulação espontânea, são metas importantes:', '["otimizar a oxigenação e a ventilação, manter a pressão arterial adequada, realizar ECG de 12 derivações e realizar controle direcionado da temperatura, prevenindo a febre.","suspender toda a monitorização.","promover hiperventilação prolongada.","manter hipotensão permissiva por tempo indeterminado.","dar alta da unidade de terapia intensiva em 24 horas."]'::jsonb, 0, 'A identificação e o tratamento da causa da PCR também são essenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-298', 'enf', null, 'No pré-natal de risco habitual, os testes rápidos para HIV e sífilis devem ser realizados:', '["na primeira consulta, no terceiro trimestre e no momento do parto ou internação, além de situações de exposição de risco.","apenas no momento do parto.","somente se a gestante relatar comportamento de risco.","apenas no primeiro trimestre.","somente quando houver sintomas."]'::jsonb, 0, 'A repetição no terceiro trimestre e no parto permite identificar infecções adquiridas durante a gestação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-299', 'enf', null, 'Gestante Rh negativo, com parceiro Rh positivo e Coombs indireto negativo. Segundo as recomendações, é indicada a imunoglobulina anti-D:', '["em situações de sensibilização (sangramentos, procedimentos invasivos, abortamento) e no pós-parto, em até 72 horas, se o recém-nascido for Rh positivo.","apenas se o Coombs indireto for positivo.","somente se o recém-nascido for Rh negativo.","em todas as gestantes, independentemente do fator Rh.","apenas após a terceira gestação."]'::jsonb, 0, 'Com Coombs indireto positivo, a gestante já está sensibilizada e deve ser acompanhada no pré-natal de alto risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-300', 'enf', null, 'Gestante suscetível à toxoplasmose (IgG e IgM não reagentes) deve ser orientada a:', '["evitar carne crua ou malpassada, lavar bem frutas e verduras, usar luvas ao mexer em terra e evitar contato com fezes de gatos.","não realizar mais nenhum exame.","tomar antibiótico profilático durante toda a gestação.","evitar qualquer contato com cães.","suspender o consumo de leite pasteurizado."]'::jsonb, 0, 'A sorologia deve ser repetida ao longo da gestação nas gestantes suscetíveis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-301', 'enf', null, 'Na gestação, a bacteriúria assintomática identificada na urocultura deve ser:', '["tratada, pois aumenta o risco de pielonefrite e de parto prematuro.","apenas observada, pois não traz riscos.","tratada somente após o parto.","tratada apenas se houver febre.","ignorada se a gestante não tiver dor."]'::jsonb, 0, 'Após o tratamento, faz-se urocultura de controle.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-302', 'enf', null, 'Segundo a Organização Mundial da Saúde, considera-se anemia na gestação a concentração de hemoglobina inferior a:', '["11 g/dL.","8 g/dL.","13 g/dL.","15 g/dL.","6 g/dL."]'::jsonb, 0, 'A suplementação de ferro e ácido fólico é recomendada no pré-natal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-303', 'enf', null, 'Associe as síndromes hipertensivas da gestação às suas definições.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-304', 'enf', null, 'Durante o acompanhamento pré-natal, considera-se critério diagnóstico de hipertensão arterial crônica na gestante:', '["PA ≥ 140 x 90 mmHg verificada antes da 20ª semana de gestação, ou hipertensão conhecida antes da gravidez.","PA ≥ 160 x 110 mmHg em uma única aferição, com proteinúria.","PA ≥ 140 x 90 mmHg que surge apenas no trabalho de parto.","PA sistólica acima de 120 mmHg antes da 10ª semana.","PA ≥ 140 x 90 mmHg detectada pela primeira vez após a 20ª semana, sem proteinúria."]'::jsonb, 0, 'A última alternativa descreve a hipertensão gestacional.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-305', 'enf', null, 'A síndrome HELLP, complicação grave da pré-eclâmpsia, caracteriza-se por:', '["hemólise, elevação das enzimas hepáticas e plaquetopenia.","hiperglicemia, leucocitose e poliúria.","hipocalcemia, edema e lombalgia.","hipotensão, hipoglicemia e febre.","hematúria, edema e linfocitose."]'::jsonb, 0, 'Pode manifestar-se com dor epigástrica ou no hipocôndrio direito, náuseas e mal-estar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-306', 'enf', null, 'No esquema de Zuspan para administração de sulfato de magnésio na pré-eclâmpsia grave, utiliza-se:', '["dose de ataque de 4 g por via endovenosa lenta, seguida de manutenção de 1 g/h em bomba de infusão.","dose única de 1 g por via oral.","10 g por via endovenosa em bolus rápido.","1 g por via subcutânea a cada 12 horas.","infusão contínua de 10 g/h."]'::jsonb, 0, 'Durante a infusão, monitoram-se reflexo patelar, frequência respiratória e diurese.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-307', 'enf', null, 'Para gestantes com alto risco de pré-eclâmpsia, o Ministério da Saúde recomenda como medida de prevenção:', '["ácido acetilsalicílico em baixa dose, iniciado a partir de 12 semanas, e suplementação de cálcio, conforme protocolo.","restrição total de sal.","repouso absoluto durante toda a gestação.","uso de diurético desde o início da gestação.","suspensão do pré-natal na Atenção Básica."]'::jsonb, 0, 'Essas medidas reduzem a incidência de pré-eclâmpsia em mulheres de alto risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-308', 'enf', null, 'Gestante no terceiro trimestre apresenta sangramento vaginal vermelho vivo, indolor, de início súbito, com útero relaxado. A principal hipótese e o cuidado de enfermagem são:', '["placenta prévia; evitar o toque vaginal e encaminhar para avaliação imediata.","descolamento prematuro de placenta; realizar toque vaginal para avaliar a dilatação.","trabalho de parto normal; orientar deambulação.","infecção urinária; coletar urocultura.","abortamento; aguardar a expulsão."]'::jsonb, 0, 'O toque vaginal pode agravar o sangramento na placenta prévia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-309', 'enf', null, 'Gestante hipertensa apresenta dor abdominal intensa, útero endurecido (hipertonia) e sangramento vaginal escuro, com sofrimento fetal. A principal hipótese diagnóstica é:', '["descolamento prematuro de placenta.","placenta prévia.","gravidez ectópica.","mola hidatiforme.","trabalho de parto prematuro sem complicações."]'::jsonb, 0, 'O sangramento pode ser oculto; é emergência obstétrica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-310', 'enf', null, 'Mulher com atraso menstrual apresenta dor abdominal intensa, sangramento vaginal discreto, hipotensão e taquicardia. A hipótese que exige atendimento imediato é:', '["gravidez ectópica rota.","dismenorreia primária.","ameaça de abortamento sem gravidade.","gestação tópica normal.","infecção urinária baixa."]'::jsonb, 0, 'A ruptura da tuba causa hemorragia intra-abdominal e choque.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-311', 'enf', null, 'No abortamento em que há sangramento, cólicas e colo uterino fechado, com embrião vivo, a classificação é:', '["ameaça de abortamento.","abortamento inevitável.","abortamento incompleto.","abortamento completo.","abortamento infectado."]'::jsonb, 0, 'No abortamento inevitável, o colo está aberto; no incompleto, há restos ovulares.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-312', 'enf', null, 'São características sugestivas de mola hidatiforme:', '["útero maior que o esperado para a idade gestacional, sangramento, hiperêmese e níveis muito elevados de hCG.","útero menor que o esperado e BCF presentes.","ausência de náuseas e hCG baixo.","dor torácica e febre.","hipotensão sem sangramento."]'::jsonb, 0, 'Pode haver eliminação de vesículas; o acompanhamento com dosagem de hCG é necessário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-313', 'enf', null, 'No trabalho de parto prematuro entre 24 e 34 semanas, a administração de corticoide à gestante (por exemplo, betametasona) tem como objetivo principal:', '["acelerar a maturação pulmonar fetal e reduzir complicações neonatais.","inibir as contrações uterinas.","tratar infecção materna.","induzir o parto.","aumentar o peso fetal."]'::jsonb, 0, 'Os tocolíticos são os medicamentos usados para inibir as contrações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-314', 'enf', null, 'O partograma é um instrumento utilizado no trabalho de parto para:', '["registrar graficamente a evolução do parto (dilatação, descida da apresentação, contrações e BCF), auxiliando a identificar distocias.","registrar apenas os dados do recém-nascido.","substituir a ausculta fetal.","prescrever medicamentos para a parturiente.","calcular a idade gestacional."]'::jsonb, 0, 'As linhas de alerta e de ação ajudam na tomada de decisão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-315', 'enf', null, 'Segundo as Diretrizes Nacionais de Assistência ao Parto Normal, na gestante de baixo risco, a ausculta intermitente dos batimentos cardíacos fetais deve ser realizada:', '["a cada 30 minutos na fase ativa e a cada 5 minutos no período expulsivo.","uma vez por hora em todo o trabalho de parto.","apenas na admissão.","a cada 2 horas na fase ativa.","somente após a rotura das membranas."]'::jsonb, 0, 'A ausculta deve durar pelo menos 1 minuto, após uma contração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-316', 'enf', null, 'Considerando as Diretrizes Nacionais de Assistência ao Parto Normal, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-317', 'enf', null, 'Durante o período expulsivo, a conduta recomendada para proteção perineal no desprendimento da cabeça fetal é:', '["controlar a deflexão da cabeça com as mãos (manobra de Ritgen modificada ou técnicas de proteção perineal) e, se desejado, usar compressa morna no períneo.","realizar expressão abdominal vigorosa.","realizar amniotomia imediatamente antes do desprendimento, mesmo com bolsa íntegra.","manter a parturiente em litotomia obrigatória, com pernas flexionadas ao máximo.","aplicar a manobra de Kristeller para acelerar o parto."]'::jsonb, 0, 'Expressão abdominal (Kristeller) não é recomendada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-318', 'enf', null, 'Na distócia de ombro, a primeira manobra recomendada, que consiste na hiperflexão das coxas da parturiente sobre o abdome, é a de:', '["McRoberts.","Kristeller.","Leopold.","Ritgen.","Valsalva."]'::jsonb, 0, 'Pode ser associada à pressão suprapúbica; é emergência obstétrica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-319', 'enf', null, 'Na classificação das lacerações perineais, a laceração de terceiro grau é aquela que envolve:', '["o complexo do esfíncter anal.","apenas a pele perineal.","a pele e os músculos do períneo, sem atingir o esfíncter anal.","a mucosa retal, além do esfíncter.","somente a mucosa vaginal."]'::jsonb, 0, 'Primeiro grau: pele/mucosa; segundo: músculos do períneo; quarto: atinge a mucosa retal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-320', 'enf', null, 'Uma das práticas recomendadas no manejo ativo do terceiro período do parto é a administração profilática de ocitocina. A via e o momento corretos são:', '["10 UI por via intramuscular, imediatamente após o nascimento do bebê.","10 UI por via intramuscular somente se a placenta não sair em 30 minutos.","5 UI por via endovenosa lenta, 30 minutos após a saída da placenta.","20 UI em 500 mL em infusão rápida durante o período expulsivo.","10 UI por via subcutânea antes do nascimento."]'::jsonb, 0, 'A ocitocina profilática é a principal medida de prevenção da hemorragia pós-parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-321', 'enf', null, 'As causas da hemorragia pós-parto são agrupadas nos "4 Ts". São eles:', '["tônus, trauma, tecido e trombina.","tempo, temperatura, tensão e taquicardia.","tumor, trauma, toxina e tosse.","tônus, tempo, toque e transfusão.","trabalho, trauma, tecido e tremor."]'::jsonb, 0, 'A atonia uterina (tônus) é a principal causa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-322', 'enf', null, 'No tratamento da hemorragia pós-parto, o ácido tranexâmico deve ser administrado:', '["precocemente, por via endovenosa, idealmente nas primeiras 3 horas após o parto.","apenas 24 horas após o parto.","por via oral, após a alta.","somente se houver febre.","em substituição à ocitocina."]'::jsonb, 0, 'Ele é adjuvante aos uterotônicos e às demais medidas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-323', 'enf', null, 'No reconhecimento precoce do choque hipovolêmico na hemorragia pós-parto, utiliza-se o índice de choque, calculado pela razão entre:', '["frequência cardíaca e pressão arterial sistólica, sendo preocupante quando igual ou superior a 0,9.","pressão diastólica e frequência respiratória.","temperatura e frequência cardíaca.","diurese e peso.","saturação e frequência cardíaca."]'::jsonb, 0, 'Valores ≥ 0,9 sugerem perda sanguínea importante e indicam medidas imediatas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-324', 'enf', null, 'No puerpério, considera-se sinal de infecção puerperal:', '["febre igual ou superior a 38 °C após as primeiras 24 horas pós-parto, com dor uterina e lóquios fétidos.","temperatura de 37 °C nas primeiras 12 horas.","lóquios rubros nos primeiros dias.","contrações uterinas durante a amamentação.","mamas tensas no terceiro dia, sem febre."]'::jsonb, 0, 'A endometrite é a forma mais comum de infecção puerperal.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-325', 'enf', null, 'A tristeza materna (baby blues) diferencia-se da depressão pós-parto porque:', '["é transitória, surge nos primeiros dias após o parto e costuma desaparecer em até duas semanas, sem prejuízo importante do funcionamento.","persiste por meses e exige internação.","envolve sempre ideação suicida.","ocorre apenas após o primeiro ano.","acomete somente mulheres sem rede de apoio."]'::jsonb, 0, 'Sintomas persistentes ou intensos devem ser investigados como depressão pós-parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-326', 'enf', null, 'O método da lactação e amenorreia (LAM) pode ser utilizado como contraceptivo quando:', '["a mulher está em amamentação exclusiva, em amenorreia e o bebê tem menos de 6 meses.","a mulher amamenta apenas uma vez por dia.","o bebê tem mais de 1 ano.","a menstruação já retornou.","a mulher usa fórmula na maior parte das mamadas."]'::jsonb, 0, 'Se qualquer critério deixar de ser atendido, é preciso outro método.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-327', 'enf', null, 'Sobre o dispositivo intrauterino (DIU) de cobre, é correto afirmar:', '["é um método de longa duração, não hormonal, que pode ser inserido inclusive no pós-parto e no pós-abortamento.","deve ser retirado após 6 meses.","protege contra infecções sexualmente transmissíveis.","é contraindicado para todas as mulheres que nunca tiveram filhos.","contém hormônio que impede a ovulação."]'::jsonb, 0, 'Pode durar até 10 anos, conforme o modelo; não protege contra IST.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-328', 'enf', null, 'Para a mulher que está amamentando e deseja um método hormonal, é recomendado evitar, nas primeiras semanas após o parto:', '["o anticoncepcional oral combinado (com estrogênio).","o preservativo masculino.","a minipílula de progestagênio.","o DIU de cobre.","o método da lactação e amenorreia."]'::jsonb, 0, 'O estrogênio pode reduzir a produção de leite e aumentar o risco de trombose no pós-parto.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-329', 'enf', null, 'Na coleta do exame citopatológico do colo do útero, é correto:', '["coletar a ectocérvice com a espátula de Ayre e a endocérvice com a escova, fixando o esfregaço na lâmina imediatamente.","usar lubrificante oleoso no espéculo para facilitar a introdução.","coletar apenas o fundo de saco vaginal.","deixar a lâmina secar ao ar por uma hora antes de fixar.","realizar a coleta durante a menstruação."]'::jsonb, 0, 'Na dificuldade, o espéculo pode ser umedecido com soro fisiológico; a fixação imediata evita dessecamento das células.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-330', 'enf', null, 'Mulher de 30 anos apresenta resultado de citopatológico com lesão intraepitelial de alto grau (HSIL). A conduta recomendada é:', '["encaminhamento para colposcopia.","repetir o exame em 3 anos.","repetir o exame em 6 meses na Atenção Básica, sem encaminhamento.","não fazer nada, por ser alteração benigna.","iniciar tratamento com antibiótico."]'::jsonb, 0, 'Atipias de menor gravidade (ASC-US, LSIL) costumam ter repetição do exame, conforme idade e diretrizes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-331', 'enf', null, 'A RDC nº 171/2006 estabelece critérios para a seleção de doadoras de leite humano. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-332', 'enf', null, 'No âmbito da Rede Alyne, a Casa da Gestante, Bebê e Puérpera é um ponto de atenção que se destina a:', '["acolher gestantes, puérperas e recém-nascidos em situação de risco que precisam permanecer próximos da maternidade de referência para acompanhamento.","realizar partos cirúrgicos.","substituir o pré-natal na Atenção Básica.","internar recém-nascidos graves em UTI.","realizar apenas consultas de planejamento reprodutivo."]'::jsonb, 0, 'É um serviço residencial transitório, vinculado à maternidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-333', 'enf', null, 'As principais causas diretas de morte materna no Brasil incluem:', '["síndromes hipertensivas, hemorragias e infecções.","acidentes de trânsito e violência urbana.","câncer de mama.","doenças cardiovasculares crônicas não relacionadas à gestação, exclusivamente.","hipotireoidismo leve."]'::jsonb, 0, 'A maioria das mortes maternas é evitável com pré-natal e assistência ao parto qualificados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-334', 'enf', null, 'Na maternidade, o recém-nascido de mãe com teste não treponêmico reagente no parto deve:', '["ser avaliado clinicamente e laboratorialmente para sífilis congênita, com notificação e tratamento conforme protocolo.","receber alta sem investigação.","receber apenas a vacina BCG.","ser separado da mãe e não ser amamentado.","aguardar a consulta de puericultura aos 30 dias."]'::jsonb, 0, 'A sífilis congênita é de notificação compulsória.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-335', 'enf', null, 'No parto de gestante vivendo com HIV, com carga viral desconhecida ou igual ou superior a 1.000 cópias/mL próximo ao parto, recomenda-se:', '["administrar zidovudina (AZT) endovenosa intraparto e inibir a lactação, além da profilaxia do recém-nascido.","estimular o aleitamento materno exclusivo.","dispensar qualquer profilaxia.","suspender a terapia antirretroviral materna.","realizar parto sem qualquer cuidado adicional."]'::jsonb, 0, 'A inibição da lactação é feita com cabergolina; o recém-nascido recebe fórmula láctea.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-336', 'enf', null, 'O recém-nascido de mãe com diabetes mal controlado na gestação deve ser monitorado, principalmente, quanto ao risco de:', '["hipoglicemia nas primeiras horas de vida, além de macrossomia e desconforto respiratório.","hiperglicemia persistente.","anemia ferropriva imediata.","hipertensão arterial neonatal.","icterícia nas primeiras 2 horas, exclusivamente."]'::jsonb, 0, 'A hiperinsulinemia fetal persiste após o nascimento, levando à hipoglicemia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-337', 'enf', null, 'Durante a assistência ao parto e no puerpério imediato, a equipe de enfermagem realiza cuidados voltados à adaptação do recém-nascido e ao vínculo entre mãe e filho. Assinale a alternativa correta.', '["O contato pele a pele na primeira hora de vida favorece o vínculo e a lactação.","O banho do recém-nascido é realizado logo após o nascimento, para a remoção do vérnix caseoso.","O clampeamento do cordão é realizado de imediato no recém-nascido a termo vigoroso.","A avaliação da vitalidade do recém-nascido é feita horas após o parto, na primeira consulta.","O recém-nascido saudável é separado da mãe logo após o parto, para observação em berço aquecido."]'::jsonb, 0, 'O banho pode ser postergado; o clampeamento oportuno ocorre após 1 a 3 minutos no RN vigoroso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
